In the following script, the mode used is "KEYWORD". It looks like we can either use "DEFAULT" or "KEYWORD". I'd like to know what each mode actually means and do we have other options apart from "DEFAULT" or "KEYWORD". 

getRelevantProblems: function(shortDesc) {
  const SCORE_THRESHOLD = 0.72;
  const MATCH_COUNT = 100;
  const FIELDS = [
   this.NUMBER_FIELD, this.SHORT_DESCRIPTION_FIELD, this.DESCRIPTION_FIELD,
   this.FIRST_REPORTED_BY_TASK_FIELD, this.CMDB_CI_FIELD, this.ACTIVE,
   this.SYS_ID, this.WORKAROUND
  ];

  const api = new sn_search.RAGRetrievalAPI();
  const ragRequest = new sn_search.RAGRetrievalRequest()
  .searchProfileId(this.SEARCH_PROFILE_ID)
  .query(shortDesc)
  .limit(MATCH_COUNT);

  ragRequest.sources([
   new sn_search.RAGRetrievalSource()
   .sourceTableName(this.PROBLEM_TABLE)
   .fields(FIELDS)
   .filter(true)
  ]);

  ragRequest.semanticConfiguration(
   new sn_search.RAGRetrievalSemanticConfiguration()
   .mode('KEYWORD')
   .documentMatchCount(MATCH_COUNT)
   .documentMatchThreshold(SCORE_THRESHOLD)
   .embeddingModelId('E5FT')
   .groupBy('ALL')
   .semanticIndexNames(['body'])
   .chunkingFormat(
    new sn_search.RAGRetrievalChunkingFormat()
    .mode('FIXED_SIZE') // Return fixed-size passages
    .chunkSize(300) // Each chunk is 300 words
    .chunkUnit('WORDS') // Set the unit to words
    .maxPassagesPerDoc(2) // Return up to 2 passages per document
   )
  );

  try {
   const ragResponse = api.retrieve(ragRequest);
   const results = JSON.parse(JSON.parse(JSON.stringify(ragResponse))).search_results;
   let problems = [];

   if (Array.isArray(results)) {
    problems = results.map(prb => prb.columns);
   }

   return {
    status: 'success',
    problems
   };
  } catch (e) {
   gs.error('Error parsing search results: ' + e);
   return {
    status: 'error',
    problems: [],
    message: 'Failed getting relevant problems'
   };
  }
 },
